function M(x){var a=Math.abs(x);return a>=1e8?(a>=1e10?Math.round(x/1e8).toLocaleString('ja-JP'):(x/1e8).toFixed(1))+'億円':a>=1e4?Math.round(x/1e4).toLocaleString('ja-JP')+'万円':Math.round(x).toLocaleString('ja-JP')+'円';}
function Y(x){return '¥'+Math.round(x).toLocaleString('ja-JP');}
function N(x){return Math.round(x).toLocaleString('ja-JP');}
var n=Math.max(0,+v('n')||0), price=Math.max(0,+v('price')||0), yr=Math.max(1,+v('yr')||1);
var y1=n/20*price*365, total=y1*yr, bars=[{label:'1年',value:y1}];
if(yr>10) bars.push({label:'10年',value:y1*10});
if(yr>1) bars.push({label:yr+'年',value:total});
Crowd.pile(el,{title:'たばこ代を積み上げると', bars:bars, fmtv:M,
  final:function(){return 'これから'+yr+'年で '+Y(total)+'。やめれば海外旅行 '+N(total/200000)+'回分が浮きます。';}});
